insert into public.projects (id, name, description, status, start_date, end_date, tags, created_at, org_id, owner_id, team_ids, settings, updated_at) values
  ('5eed2026-0001-4000-8000-000000000001', 'Entomate 1.0 launch', 'Ship the 1.0 release: meeting capture, recaps, follow-through and the public site.', 'active', '2026-10-05', '2026-12-15', '["launch", "product"]'::jsonb, '2026-10-05T15:00:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', null, '{}', '{"seed": "demo-seed-2026-11-22"}'::jsonb, '2026-10-05T15:00:00Z'),
  ('5eed2026-0001-4000-8000-000000000002', 'Bluepine Clinics pilot', 'Eight-week pilot with Bluepine Clinics operations: weekly huddles recorded and followed up in Entomate.', 'active', '2026-10-12', '2026-12-04', '["pilot", "customer"]'::jsonb, '2026-10-12T15:00:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', null, '{}', '{"seed": "demo-seed-2026-11-22"}'::jsonb, '2026-10-12T15:00:00Z'),
  ('5eed2026-0001-4000-8000-000000000003', 'Calendar auto-join', 'Let the meeting bot join calendar meetings on its own, with consent and opt-out.', 'planning', '2026-11-24', '2027-01-15', '["bots", "calendar"]'::jsonb, '2026-10-29T18:00:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', null, '{}', '{"seed": "demo-seed-2026-11-22"}'::jsonb, '2026-10-29T18:00:00Z'),
  ('5eed2026-0001-4000-8000-000000000004', 'Brand refresh', 'Aperture mark, Void Crimson palette and the new landing page.', 'completed', '2026-09-14', '2026-11-13', '["brand", "design"]'::jsonb, '2026-09-14T15:00:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', null, '{}', '{"seed": "demo-seed-2026-11-22"}'::jsonb, '2026-09-14T15:00:00Z')
insert into public.meetings (id, org_id, title, description, transcript, summary, key_points, decisions, topics, sentiment_label, sentiment_score, start_time, end_time, duration_minutes, attendees, created_by, project_id, transcript_segments, summary_moments, created_at, updated_at) values
  ('5eed2026-0002-4000-8000-000000000001', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Bluepine pilot kickoff', null, null, 'Kickoff for the eight-week Bluepine Clinics pilot. Bluepine''s Tuesday operations huddles lose about half their follow-ups by Thursday; Entomate will record those huddles and give every action item an owner and a due date. The team agreed an 80% on-time target by week six (baseline about 50%) and a check-in every two weeks. Consent comes first: every clinic lead must see the notice before recording starts.', '["Half of huddle follow-ups are lost by Thursday today.", "Sam wants a weekly view of who is behind without chasing in Slack.", "Target: 80% of action items closed on time by week six.", "Clinic leads must see the consent notice before any recording."]'::jsonb, '["Pilot runs eight weeks, Tuesday huddles only, with an 80% on-time target.", "Check-ins every two weeks at the same time."]'::jsonb, '["Pilot scope", "Success metrics", "Recording consent", "Weekly cadence"]'::jsonb, 'Positive', 0.72, '2026-10-14T15:00:00Z', '2026-10-14T15:34:00Z', 34, '["Frank Messana", "Priya Shah", "Sam Whitaker", "Dana Ortiz"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000002', '[{"atMs": 4000, "endMs": 14980, "speaker": "Frank Messana", "text": "Thanks for making the time, Sam. Goal today is to agree what the pilot covers and how we''ll know it worked."}, {"atMs": 18280, "endMs": 28120, "speaker": "Sam Whitaker", "text": "Sure. Our ops huddles run every Tuesday and half the follow-ups get lost by Thursday. That''s the pain."}, {"atMs": 33220, "endMs": 44200, "speaker": "Priya Shah", "text": "So we record the Tuesday huddle, and every action item gets an owner and a date before people leave the call."}, {"atMs": 49300, "endMs": 58000, "speaker": "Sam Whitaker", "text": "Right. And I need a weekly view of who''s behind, without chasing people in Slack."}, {"atMs": 63100, "endMs": 71040, "speaker": "Dana Ortiz", "text": "We can give you follow-through by owner. On-time rate per person, per week."}, {"atMs": 77040, "endMs": 86120, "speaker": "Frank Messana", "text": "Let''s set the bar: eighty percent of huddle action items closed on time by week six."}, {"atMs": 87620, "endMs": 94420, "speaker": "Sam Whitaker", "text": "Eighty is ambitious but fair. We''re at maybe fifty today."}, {"atMs": 96820, "endMs": 105900, "speaker": "Priya Shah", "text": "One thing before we record anything. Every clinic lead needs to see the consent notice first."}, {"atMs": 109200, "endMs": 116760, "speaker": "Sam Whitaker", "text": "Legal will want the notice text. Can you send it this week?"}, {"atMs": 120960, "endMs": 128140, "speaker": "Dana Ortiz", "text": "I''ll send the consent notice and the opt-out link by Friday."}, {"atMs": 133240, "endMs": 141180, "speaker": "Frank Messana", "text": "Decision then: pilot runs eight weeks, Tuesday huddles only, eighty percent on-time target."}, {"atMs": 142680, "endMs": 150240, "speaker": "Sam Whitaker", "text": "Agreed. I''ll send you the list of clinic leads and their emails."}, {"atMs": 152640, "endMs": 160960, "speaker": "Priya Shah", "text": "And I''ll set up the workspace and invite them once the list comes in."}, {"atMs": 167860, "endMs": 174280, "speaker": "Frank Messana", "text": "Great. We check in every two weeks, same time."}]'::jsonb, '{"decisions": [133240, 167860], "keyPoints": [18280, 49300, 77040, 96820]}'::jsonb, '2026-10-14T15:37:00Z', '2026-10-14T15:38:00Z'),
  ('5eed2026-0002-4000-8000-000000000002', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Weekly product sync', null, null, 'Recaps are solid on short meetings but the decisions section thins out past forty minutes, mostly because the whole transcript is summarised at once. Marcus will prototype chunked summaries. Speaker renaming is in scope for 1.0, and CRM sync is cut from 1.0 because no pilot customer uses a CRM.', '["Decisions get thin on meetings longer than forty minutes.", "Plan: chunk long transcripts and merge the summaries.", "Users want real speaker names, not Speaker 1 and 2."]'::jsonb, '["Speaker renaming ships in 1.0.", "CRM sync moves to after launch."]'::jsonb, '["Recap quality", "Speaker labels", "Launch scope"]'::jsonb, 'Neutral', 0.12, '2026-10-21T16:00:00Z', '2026-10-21T16:28:00Z', 28, '["Frank Messana", "Priya Shah", "Marcus Lee", "Lena Park"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000001', '[{"atMs": 4000, "endMs": 10420, "speaker": "Frank Messana", "text": "Quick one today. Where are we on recap quality?"}, {"atMs": 16420, "endMs": 25500, "speaker": "Marcus Lee", "text": "Recaps are good on short meetings. On anything over forty minutes the decisions section gets thin."}, {"atMs": 27000, "endMs": 32660, "speaker": "Priya Shah", "text": "Is that the model or the prompt?"}, {"atMs": 37760, "endMs": 47220, "speaker": "Marcus Lee", "text": "Mostly the prompt. We summarise the whole transcript at once. I want to chunk it and merge."}, {"atMs": 48720, "endMs": 58560, "speaker": "Lena Park", "text": "From the design side, people keep asking who said what. Speaker labels are just Speaker 1, Speaker 2."}, {"atMs": 62760, "endMs": 70700, "speaker": "Frank Messana", "text": "Renaming speakers has to be in 1.0. It''s the first thing anyone does."}, {"atMs": 77600, "endMs": 84780, "speaker": "Marcus Lee", "text": "Rename is easy. I can have it in by next week."}, {"atMs": 89880, "endMs": 100100, "speaker": "Priya Shah", "text": "Then let''s cut the CRM sync from 1.0. It''s half done and nobody in the pilot uses a CRM."}, {"atMs": 105200, "endMs": 110480, "speaker": "Frank Messana", "text": "Agreed, CRM moves to after launch."}, {"atMs": 117380, "endMs": 123800, "speaker": "Lena Park", "text": "I''ll mock the transcript viewer with rename and jump-to-moment."}, {"atMs": 125300, "endMs": 133240, "speaker": "Marcus Lee", "text": "And I''ll prototype the chunked summary on the three longest meetings we have."}]'::jsonb, '{"decisions": [62760, 105200], "keyPoints": [16420, 37760, 48720]}'::jsonb, '2026-10-21T16:31:00Z', '2026-10-21T16:32:00Z'),
  ('5eed2026-0002-4000-8000-000000000003', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Calendar auto-join design review', null, null, 'Design review for calendar auto-join. Consent is the main risk because external guests have not agreed to anything. For v1 the bot joins only meetings the user organised, and every external attendee gets an opt-out email 24 hours ahead (or at booking time for sooner meetings). Bot join failures must never be silent: the organiser is told and the meeting shows as missed.', '["External guests have not consented, which is the main risk.", "Opt-out email goes out 24 hours ahead or at booking time.", "Both test bots failed silently last week."]'::jsonb, '["v1 auto-joins only meetings the user organised, with a 24-hour opt-out email.", "Bot join failures notify the organiser and mark the meeting as missed."]'::jsonb, '["Consent", "Which meetings to join", "Opt-out email", "Failure handling"]'::jsonb, 'Mixed', -0.05, '2026-10-29T18:00:00Z', '2026-10-29T18:41:00Z', 41, '["Frank Messana", "Priya Shah", "Marcus Lee", "Dana Ortiz"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000003', '[{"atMs": 4000, "endMs": 12700, "speaker": "Priya Shah", "text": "The ask is simple: the bot joins your calendar meetings without you pasting a link."}, {"atMs": 19600, "endMs": 28300, "speaker": "Dana Ortiz", "text": "Simple to say. The consent part is the hard bit. External guests didn''t sign anything."}, {"atMs": 31600, "endMs": 39160, "speaker": "Frank Messana", "text": "So we only auto-join meetings the user organised, at least to start."}, {"atMs": 45160, "endMs": 51960, "speaker": "Marcus Lee", "text": "That''s one flag on the calendar event. Easy to check."}, {"atMs": 57060, "endMs": 65380, "speaker": "Dana Ortiz", "text": "And every external attendee gets an email before the meeting with a one-click opt-out."}, {"atMs": 68680, "endMs": 75480, "speaker": "Priya Shah", "text": "How long before? If it''s five minutes, nobody reads it."}, {"atMs": 82380, "endMs": 89560, "speaker": "Dana Ortiz", "text": "Twenty-four hours, or at booking time if the meeting is sooner."}, {"atMs": 91060, "endMs": 99760, "speaker": "Marcus Lee", "text": "What happens if the bot fails to join? Last week both test bots failed silently."}, {"atMs": 103960, "endMs": 112280, "speaker": "Frank Messana", "text": "That can''t be silent. The organiser gets told, and the meeting shows as missed."}, {"atMs": 115580, "endMs": 123520, "speaker": "Priya Shah", "text": "Decision: v1 joins only meetings you organised, with a twenty-four hour opt-out email."}, {"atMs": 126820, "endMs": 135140, "speaker": "Marcus Lee", "text": "I''ll write up the bot failure states and what the user sees for each."}, {"atMs": 142040, "endMs": 149600, "speaker": "Dana Ortiz", "text": "I''ll draft the opt-out email and get legal to look at it."}, {"atMs": 152000, "endMs": 159560, "speaker": "Frank Messana", "text": "And Priya, can you write the spec so we can estimate it?"}]'::jsonb, '{"decisions": [115580, 103960], "keyPoints": [19600, 82380, 91060]}'::jsonb, '2026-10-29T18:44:00Z', '2026-10-29T18:45:00Z'),
  ('5eed2026-0002-4000-8000-000000000004', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Bluepine check-in, week 3', null, null, 'Week-three check-in. On-time follow-through is up from about 50% to 68%. The remaining gap is items nobody claims. Rather than lowering the assignment agent''s 70% confidence bar, the team will flag unowned items in the recap. Two clinics (Westside and Harbor Road) have not recorded a huddle yet; Dana will walk their leads through it.', '["On-time rate is 68%, up from 50% at kickoff.", "Unclaimed items are the biggest remaining gap.", "Westside and Harbor Road have not recorded a huddle yet."]'::jsonb, '["Flag unowned items in the recap instead of lowering the assignment confidence bar."]'::jsonb, '["On-time rate", "Unassigned items", "Clinic adoption"]'::jsonb, 'Positive', 0.55, '2026-11-04T15:00:00Z', '2026-11-04T15:26:00Z', 26, '["Frank Messana", "Sam Whitaker", "Dana Ortiz"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000002', '[{"atMs": 4000, "endMs": 11180, "speaker": "Sam Whitaker", "text": "Numbers first. We''re at sixty-eight percent on time, up from fifty."}, {"atMs": 16280, "endMs": 23460, "speaker": "Frank Messana", "text": "That''s a real jump in three weeks. What''s dragging the rest?"}, {"atMs": 28560, "endMs": 36880, "speaker": "Sam Whitaker", "text": "Items nobody claims. Someone says we should look into it and it goes nowhere."}, {"atMs": 38380, "endMs": 48220, "speaker": "Dana Ortiz", "text": "The assignment agent catches most of those, but it''s cautious. It only assigns when it''s seventy percent sure."}, {"atMs": 54220, "endMs": 59500, "speaker": "Frank Messana", "text": "Can we lower that for Bluepine?"}, {"atMs": 63700, "endMs": 73160, "speaker": "Dana Ortiz", "text": "We can, but then it guesses wrong more often. I''d rather flag unowned items in the recap."}, {"atMs": 79160, "endMs": 85200, "speaker": "Sam Whitaker", "text": "Flagging works. My leads read the recap anyway."}, {"atMs": 91200, "endMs": 100280, "speaker": "Frank Messana", "text": "Then let''s turn on the follow-up flag for Bluepine and keep the bar where it is."}, {"atMs": 104480, "endMs": 112040, "speaker": "Sam Whitaker", "text": "Two clinics still haven''t recorded a single huddle. Westside and Harbor Road."}, {"atMs": 113540, "endMs": 121480, "speaker": "Dana Ortiz", "text": "I''ll reach out to both leads this week and walk them through it."}]'::jsonb, '{"decisions": [91200], "keyPoints": [4000, 28560, 104480]}'::jsonb, '2026-11-04T15:29:00Z', '2026-11-04T15:30:00Z'),
  ('5eed2026-0002-4000-8000-000000000005', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Weekly product sync', null, null, 'Chunked summaries shipped and tripled the decisions found on long meetings (five of six checked were real). Search was missing meetings because embeddings were never stored after the embedding model was retired; that is fixed and old meetings need a backfill. On phones the transcript should be one tap from the recap, which is a launch requirement.', '["Chunked summaries raised decisions found on long meetings from two to six.", "Embeddings were not stored because the model was retired; now fixed.", "On phones the transcript is three taps deep."]'::jsonb, '["Ship chunked summaries.", "Transcript is one tap from the recap on phones for launch."]'::jsonb, '["Chunked summaries", "Search", "Mobile layout"]'::jsonb, 'Neutral', 0.2, '2026-11-10T16:00:00Z', '2026-11-10T16:31:00Z', 31, '["Frank Messana", "Priya Shah", "Marcus Lee", "Lena Park"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000001', '[{"atMs": 4000, "endMs": 13080, "speaker": "Marcus Lee", "text": "Chunked summaries are in. On the long meetings the decision count went from two to six."}, {"atMs": 17280, "endMs": 23320, "speaker": "Priya Shah", "text": "Did anyone check the six are real decisions?"}, {"atMs": 26620, "endMs": 34180, "speaker": "Marcus Lee", "text": "I checked by hand. Five were real, one was a restated goal."}, {"atMs": 38380, "endMs": 44420, "speaker": "Frank Messana", "text": "Five out of six is fine. Ship it."}, {"atMs": 50420, "endMs": 58740, "speaker": "Lena Park", "text": "Search needs work. Typing a decision word doesn''t find the meeting it came from."}, {"atMs": 62940, "endMs": 70880, "speaker": "Marcus Lee", "text": "Embeddings weren''t being stored. The embedding model name was retired. It''s fixed now."}, {"atMs": 74180, "endMs": 80220, "speaker": "Priya Shah", "text": "Then we need to backfill every old meeting."}, {"atMs": 82620, "endMs": 90560, "speaker": "Marcus Lee", "text": "There''s a nightly job for that now. I''ll run it by hand today."}, {"atMs": 97460, "endMs": 105400, "speaker": "Lena Park", "text": "Last thing, the meeting page on phones. The transcript is three taps deep."}, {"atMs": 110500, "endMs": 118440, "speaker": "Frank Messana", "text": "Put the transcript one tap from the recap. That''s a must for launch."}, {"atMs": 124440, "endMs": 130860, "speaker": "Lena Park", "text": "I''ll have the phone layout ready for review Friday."}]'::jsonb, '{"decisions": [38380, 110500], "keyPoints": [4000, 62940, 97460]}'::jsonb, '2026-11-10T16:34:00Z', '2026-11-10T16:35:00Z'),
  ('5eed2026-0002-4000-8000-000000000006', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Brand refresh sign-off', null, null, 'Sign-off on the brand refresh. The Aperture mark on the Void Crimson palette is the brand; older marks are retired to the archive. The landing page already uses it, with rotating hero films. Remaining work is the app icons, PWA manifest and a packaged asset kit.', '["Aperture mark delivered in four colourways with two lockups.", "Crimson on dark holds up at favicon size.", "Landing page already uses the new brand."]'::jsonb, '["Aperture on Void Crimson is the brand; old marks are retired."]'::jsonb, '["Aperture mark", "Palette", "Landing page"]'::jsonb, 'Positive', 0.8, '2026-11-13T17:00:00Z', '2026-11-13T17:22:00Z', 22, '["Frank Messana", "Lena Park", "Priya Shah"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000004', '[{"atMs": 4000, "endMs": 12700, "speaker": "Lena Park", "text": "Final files are up. Aperture mark in four colourways, plus the horizontal and stacked lockups."}, {"atMs": 16900, "endMs": 24840, "speaker": "Frank Messana", "text": "The crimson on dark is the one. It reads at favicon size too."}, {"atMs": 30840, "endMs": 36880, "speaker": "Priya Shah", "text": "Do we keep the old hex mark anywhere?"}, {"atMs": 40180, "endMs": 46600, "speaker": "Lena Park", "text": "Only in the archive. Everything public moves to Aperture."}, {"atMs": 49000, "endMs": 56560, "speaker": "Frank Messana", "text": "Decision: Aperture on Void Crimson is the brand. Old marks are retired."}, {"atMs": 58960, "endMs": 66900, "speaker": "Lena Park", "text": "The landing page is built on it already. Rotating hero films are in."}, {"atMs": 72900, "endMs": 80080, "speaker": "Priya Shah", "text": "I''ll update the app icons and the PWA manifest to match."}, {"atMs": 81580, "endMs": 89140, "speaker": "Frank Messana", "text": "And Lena, package the asset kit so the team can grab it."}]'::jsonb, '{"decisions": [49000], "keyPoints": [4000, 16900, 58960]}'::jsonb, '2026-11-13T17:25:00Z', '2026-11-13T17:26:00Z'),
  ('5eed2026-0002-4000-8000-000000000007', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Launch readiness review', null, null, 'Launch readiness for December 1. The task status bug is fixed. Open blockers: Insights is empty for new workspaces (needs a first-run state), automation runs are never recorded because the executor writes a status the table rejects, and the pricing page. Pricing is per workspace with a meeting-hours cap. Launch date holds, with a final go/no-go on November 26.', '["Three blockers: task status, empty Insights, pricing.", "Task status bug is fixed.", "Automation runs are not recorded because of a status mismatch."]'::jsonb, '["Pricing is per workspace with a meeting-hours cap.", "Launch stays December 1; go/no-go on November 26."]'::jsonb, '["Launch date", "Open blockers", "Status bug", "Pricing page"]'::jsonb, 'Mixed', 0.05, '2026-11-18T16:00:00Z', '2026-11-18T16:45:00Z', 45, '["Frank Messana", "Priya Shah", "Marcus Lee", "Dana Ortiz", "Lena Park"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000001', '[{"atMs": 4000, "endMs": 10040, "speaker": "Frank Messana", "text": "We said December first. Are we still there?"}, {"atMs": 12440, "endMs": 21520, "speaker": "Priya Shah", "text": "Close. Three blockers. The task status bug, the empty Insights page for new workspaces, and pricing."}, {"atMs": 24820, "endMs": 35040, "speaker": "Marcus Lee", "text": "The status bug is fixed. The database only allowed the old status names, so new tasks failed to save."}, {"atMs": 39240, "endMs": 48700, "speaker": "Dana Ortiz", "text": "Insights is empty for new workspaces because there''s nothing to count. We need a better first-run state."}, {"atMs": 55600, "endMs": 64680, "speaker": "Lena Park", "text": "I can design that. Show the three numbers with a line on how they fill in."}, {"atMs": 69780, "endMs": 76960, "speaker": "Frank Messana", "text": "Pricing. We still haven''t picked between per seat and per workspace."}, {"atMs": 82960, "endMs": 89760, "speaker": "Priya Shah", "text": "Pilot feedback says per workspace. Small teams hate seat math."}, {"atMs": 96660, "endMs": 103080, "speaker": "Frank Messana", "text": "Then per workspace, with a meeting-hours cap. Decision made."}, {"atMs": 108180, "endMs": 116880, "speaker": "Marcus Lee", "text": "Automations also never record a run. The executor writes a status the table doesn''t accept."}, {"atMs": 118380, "endMs": 126700, "speaker": "Frank Messana", "text": "That has to be fixed before launch. People need to see their automations worked."}, {"atMs": 130900, "endMs": 137320, "speaker": "Marcus Lee", "text": "I''ll fix the run status and add a test."}, {"atMs": 142420, "endMs": 149220, "speaker": "Dana Ortiz", "text": "I''ll write the pricing page copy with the hours cap."}, {"atMs": 153420, "endMs": 160600, "speaker": "Frank Messana", "text": "We hold December first. Final go or no-go on the twenty-sixth."}]'::jsonb, '{"decisions": [96660, 153420], "keyPoints": [12440, 24820, 108180]}'::jsonb, '2026-11-18T16:48:00Z', '2026-11-18T16:49:00Z'),
  ('5eed2026-0002-4000-8000-000000000008', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'Bluepine renewal prep', null, null, 'Renewal prep for Bluepine. On-time follow-through reached 79%, one point under the 80% target and up from 50%. All clinics are now recording. The renewal will lead with the improvement, offer the regional managers'' meeting at the same price for the first quarter, and ask Sam for a case study.', '["On-time rate is 79%, up from 50%.", "Every clinic records now.", "Bluepine wants to add the regional managers meeting."]'::jsonb, '["Offer the regional managers meeting at the same price for Q1.", "Lead the renewal with the 50% to 79% improvement."]'::jsonb, '["Pilot results", "Renewal terms", "Case study"]'::jsonb, 'Positive', 0.6, '2026-11-20T15:30:00Z', '2026-11-20T15:54:00Z', 24, '["Frank Messana", "Priya Shah", "Dana Ortiz"]'::jsonb, 'ee73a786-a84b-4540-b920-43c1a39c396a', '5eed2026-0001-4000-8000-000000000002', '[{"atMs": 4000, "endMs": 10420, "speaker": "Frank Messana", "text": "Bluepine pilot ends December fourth. Let''s prep the renewal."}, {"atMs": 15520, "endMs": 23080, "speaker": "Dana Ortiz", "text": "Latest number is seventy-nine percent on time. One point off the target."}, {"atMs": 26380, "endMs": 33180, "speaker": "Priya Shah", "text": "And every clinic records now, Westside and Harbor Road included."}, {"atMs": 35580, "endMs": 43520, "speaker": "Frank Messana", "text": "Good. We lead with the jump from fifty to seventy-nine, not the miss."}, {"atMs": 50420, "endMs": 56460, "speaker": "Dana Ortiz", "text": "Sam asked about adding their regional managers'' meeting."}, {"atMs": 57960, "endMs": 65140, "speaker": "Frank Messana", "text": "Offer it in the renewal. Same price for the first quarter."}, {"atMs": 68440, "endMs": 74100, "speaker": "Priya Shah", "text": "Can we ask for a case study?"}, {"atMs": 75600, "endMs": 83920, "speaker": "Frank Messana", "text": "Yes, ask Sam on the next call. Priya, draft the one-pager with the numbers."}, {"atMs": 89920, "endMs": 95960, "speaker": "Dana Ortiz", "text": "I''ll put the renewal proposal together by Tuesday."}]'::jsonb, '{"decisions": [57960, 35580], "keyPoints": [15520, 26380, 50420]}'::jsonb, '2026-11-20T15:57:00Z', '2026-11-20T15:58:00Z')
insert into public.action_items (id, org_id, meeting_id, task_description, context, assigned_to_name, assigned_to_email, due_date, priority, status, crm_sync_status, transcript_at_ms, agent_notes, created_at, updated_at, completed_at) values
