insert into public.meeting_notes (id, meeting_id, body, visibility, created_at, org_id, author_id, author_name, updated_at) values
  ('5eed2026-0007-4000-8000-000000000001', '5eed2026-0002-4000-8000-000000000001', 'Sam cares about the weekly owner view more than the recap itself. Lead with that in every check-in.', 'team', '2026-10-14T16:00:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'ee73a786-a84b-4540-b920-43c1a39c396a', 'Frank Messana', '2026-10-14T16:00:00Z'),
  ('5eed2026-0007-4000-8000-000000000002', '5eed2026-0002-4000-8000-000000000007', 'Go/no-go hinges on the run status fix. If it slips past the 24th, push launch a week.', 'private', '2026-11-18T17:00:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'ee73a786-a84b-4540-b920-43c1a39c396a', 'Frank Messana', '2026-11-18T17:00:00Z'),
  ('5eed2026-0007-4000-8000-000000000003', '5eed2026-0002-4000-8000-000000000008', 'Bring the 50% to 79% chart. Do not open with the one-point miss.', 'team', '2026-11-20T16:10:00Z', 'a993efd7-4360-4d38-aeb1-f2202632706c', 'ee73a786-a84b-4540-b920-43c1a39c396a', 'Frank Messana', '2026-11-20T16:10:00Z')
